styles:
.b-showcase-zoom {
    container-type: inline-size;
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-zoom__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-zoom__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

/* The container the zoom measures its room in: the picture and the text beside it. */
.b-showcase-zoom__frame {
    container-type: inline-size;
}

.b-showcase-zoom--product .b-showcase-zoom__frame {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: var(--site-space-6);
    align-items: start;
}

.b-showcase-zoom--narrow .b-showcase-zoom__frame {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}

.b-showcase-zoom__title {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-zoom__price {
    font-size: var(--site-font-size-3);
    font-weight: 600;
}

/* A phone: the text under the picture, and no room beside it. */
@container (max-width: 40rem) {
    .b-showcase-zoom--product .b-showcase-zoom__frame {
        grid-template-columns: minmax(0, 1fr);
    }
}
